<?php

declare(strict_types=1);

namespace RainCity\REDCap;

use Psr\Log\LoggerInterface;
use Psr\SimpleCache\CacheInterface;
use Symfony\Component\Lock\LockFactory;
use IU\PHPCap\PhpCapException;

/**
 * Extension of \IU\PHPCap\RedCapProject
 *
 * Unless provided with an error handler, utilizes RedCapErrorHandler
 * to log errors generated by RedCapProject.
 *
 * Also extends/wraps parent methods to ensure a default/empty value is
 * returned from member methods.
 *
 * @see RedCapErrorHandler
 * @see \IU\PHPCap\RedCapProject
 */
class RedCapProject extends \IU\PHPCap\RedCapProject
{
    private const DEFAULT_TTL = 15 * 60;    // 15 minutes

    private int $ttl;
    private string $cacheKey;

    /**
     * Construct and instance
     *
     * @param RedCapConfigIntf $config An object with the REDCap configuration information
     * @param CacheInterface $cache The cache for caching responses
     * @param LockFactory $lockFactory A reference to a Symfony/LockFactory
     * @param LoggerInterface $logger The object to use for logging
     */
    public function __construct(
        RedCapConfigIntf $config,
        private CacheInterface $cache,
        private LockFactory $lockFactory,
        private LoggerInterface $logger
    ) {
        parent::__construct(
            $config->getApiUrl(),
            $config->getApiToken(),
            $config->getSslVerify(),
            $config->getCaCertificateFile(),
            $config->getErrorHandler() ?? new RedCapErrorHandler($logger),
            $config->getConnection()
        );

        $this->ttl = self::DEFAULT_TTL;
        $this->cacheKey = hash(
            'sha256',
            parse_url($this->getConnection()->getUrl(), PHP_URL_HOST) . '-' . $config->getApiToken()
        );
    }

    /**
     * Fetch the hash value representing this project instance.
     *
     * Note that different RedCapProject instances using the same host and
     * API Token will return the same hash value.
     *
     * @return string The hash value for the project object.
     */
    public function getHash(): string
    {
        return $this->cacheKey;
    }

    /**
     * Set the TTL for new items added to the cache.
     * 
     * @param int|null $seconds The number of seconds to cache responses from
     *      the server. If null is passed the TTL is reset to the default
     *      which is 15 minutes.
     *
     * @return void 
     */
    public function setCacheTTL(?int $seconds): void
    {
        assert(
            is_null($seconds) || 0 < $seconds,
            'Number of seconds passed to setCacheTTL must be null or greater that 0'
        );

        $this->ttl = $seconds ?? self::DEFAULT_TTL;
    }

    /**
     * Fetch the result of the specified function from the cache or make the
     * actual call if necessary.
     *
     * This function should only be used for calls which generally result in
     * the same response each time they are called.
     *
     * The results of calls are stored in the cache using a key based on the
     * function name, the arguments passed to the function, the REDCap host
     * name and the API key.
     * 
     * Utilizes a lock so that only one request of a given API is called at a
     * time. This prevents two or more calls on the same API which could
     * negate the value of the cache. And example would be when new and
     * completed surveys are being rendered asynchronously.
     *
     * @param string $func The name of the function call.
     * @param array<mixed> $args The array of arguments passed to the original call,
     *      retreived via func_get_args().
     *
     * @return mixed The result of the function call retreived from the cache
     *      or the server response.
     */
    private function maybeCallParentFunction(string $func, array $args): mixed
    {
        $result = null;

        $cacheKey = sprintf('%s-%s-%s', $func, json_encode($args), $this->cacheKey);

        $lock = $this->lockFactory->createLock($cacheKey, 60.0);

        try {
            $lock->acquire(true);

            if ($lock->isAcquired()) {
                $result = $this->cache->get($cacheKey);
                if (!isset($result)) {
                    $scopeTimer = new \RCS\Logging\ScopeTimer(
                        $this->logger,
                        'Time to call REDCap function ' . $func . '(): %s'
                    );

                    $result = call_user_func_array(parent::class . '::' . $func, $args);

                    if (isset($result)) {
                        $this->cache->set($cacheKey, $result, $this->ttl);
                    }
                }
            } else {
                $this->logger->critical('Unable to obtain lock while executing REDCap API request');
            }
        } finally {
            $lock->release();
        }

        return $result;
    }

    /**
     *
     * {@inheritDoc}
     * @see \IU\PHPCap\RedCapProject::exportRedcapVersion()
     */
    public function exportRedcapVersion()
    {
        $result = null;

        try {
            $result = $this->maybeCallParentFunction(__FUNCTION__, func_get_args());
        } catch (PhpCapException $exception) {
        }

        return $result;
    }


    /**
     * @param string $format
     * @return mixed
     *
     * {@inheritDoc}
     * @see \IU\PHPCap\RedCapProject::exportInstruments()
     */
    public function exportInstruments($format = 'php'): mixed
    {
        $result = null;

        try {
            $result = $this->maybeCallParentFunction(__FUNCTION__, func_get_args());
        } catch (PhpCapException $exception) {
            if ('php' == $format) {
                $result = array();
            } else {
                $result = '{}';
            }
        }

        return $result;
    }


    /**
     *
     * @param string[] $arms
     *
     * @return mixed
     * {@inheritDoc}
     * @see \IU\PHPCap\RedCapProject::exportInstrumentEventMappings()
     */
    public function exportInstrumentEventMappings($format = 'php', $arms = [])
    {
        $result = null;

        try {
            $result = $this->maybeCallParentFunction(__FUNCTION__, func_get_args());
