    public function exportPdfFileOfInstruments(
        $file = null,
        $recordId = null,
        $event = null,
        $form = null,
        $allRecords = null,
        $compactDisplay = null,
        $repeatInstance = null
    ) {
        $result = '';

        try {
            $result = parent::exportPdfFileOfInstruments(
                $file,
                $recordId,
                $event,
                $form,
                $allRecords,
                $compactDisplay,
                $repeatInstance
            );
        } catch (PhpCapException $exception) {
        }

        return $result;
    }

