    public function exportRecords(
        $format = 'php',
        $type = 'flat',
        $recordIds = null,
        $fields = null,
        $forms = null,
        $events = null,
        $filterLogic = null,
        $rawOrLabel = 'raw',
        $rawOrLabelHeaders = 'raw',
        $exportCheckboxLabel = false,
        $exportSurveyFields = false,
        $exportDataAccessGroups = false,
        $dateRangeBegin = null,
        $dateRangeEnd = null,
        $csvDelimiter = ',',
        $decimalCharacter = null,
        $exportBlankForGrayFormStatus = false
    ) {
        $result = null;

        try {
            $result = parent::exportRecords(
                $format,
                $type,
                $recordIds,
                $fields,
                $forms,
                $events,
                $filterLogic,
                $rawOrLabel,
                $rawOrLabelHeaders,
                $exportCheckboxLabel,
                $exportSurveyFields,
                $exportDataAccessGroups,
                $dateRangeBegin,
                $dateRangeEnd,
                $csvDelimiter,
                $decimalCharacter
            );
        } catch (PhpCapException $exception) {
            if ('php' == $format) {
                $result = array();
            } else {
                $result = '{}';
            }
        }

        return $result;
    }

